// Берем бинарные данные из предыдущей ноды
const binaryData = $binary.data;

// Меняем MIME-тип на правильный для JPEG
binaryData.mimeType = 'image/jpeg';

// Возвращаем данные дальше по цепочке
return [{
  json: $json,
  binary: {
    data: binaryData
  }
}];

const geminiText = $json.content?.parts?.[0]?.text || '';

// Возвращаем в формате, как будто это пришло от Telegram
return [{
  json: {
    message: {
      text: geminiText,
      chat: {
        id: $('Telegram Trigger').item.json.message.chat.id
      }
    }
  }
}];

const resp = $input.first().json;
const r = resp?.result;

let recognizedText = null;
if (typeof r === 'string' && r.trim()) {
  recognizedText = r.trim();                                   
} else if (Array.isArray(r?.alternatives) && r.alternatives[0]?.text) {
  recognizedText = r.alternatives[0].text;                     
}

const chatId = $('Telegram Trigger').first().json.message.chat.id;

return [{
  json: {
    message: {
      text: recognizedText
        ? recognizedText
        : '[система]: пользователь прислал голосовое сообщение, но распознавание не удалось (речь не содержит слов или ошибка SpeechKit). Извинись и попроси продублировать запрос текстом.',
      chat: { id: chatId }
    }
  }
}];

// ============================================
// PARSER: JSON для презентаций/докладов
// ============================================
const raw = $json.output || $json.text || '';
const chatId = $json.chatId || $('Telegram Trigger').first().json.message.chat.id;

/**
 * Извлекает JSON из ответа агента
 * Ищет: 1) в fenced code blocks ```json ... ```, 2) в чистом тексте { ... }
 */
function extractJson(text) {
  // Пробуем найти fenced code block
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1] : text;

  // Ищем начало и конец JSON-объекта
  const s = candidate.indexOf('{');
  const e = candidate.lastIndexOf('}');

  if (s === -1 || e <= s) return null;

  try {
    return JSON.parse(candidate.slice(s, e + 1));
  } catch {
    return null;
  }
}

// Пробуем распарсить JSON
const parsed = extractJson(raw);

// Если это презентация
if (parsed?.type === 'presentation') {
  return [{
    json: {
      isPresentation: true,
      isWord: false,
      presentationData: parsed,
      chatId: chatId
    }
  }];
}

// Если это доклад
if (parsed?.type === 'word_document') {
  return [{
    json: {
      isPresentation: false,
      isWord: true,
      wordData: parsed,
      chatId: chatId
    }
  }];
}

// FALLBACK: обычный текстовый ответ
// ВАЖНО: возвращаем ОРИГИНАЛЬНЫЙ raw, а не очищенный!
// Бэктики остаются на месте для markdown-форматирования кода
return [{
  json: {
    isPresentation: false,
    isWord: false,
    text: raw,
    chatId: chatId,
    // Флаг для будущей retry-логики (P2.4):
    // если агент пытался сделать презентацию/доклад, но JSON не распарсился
    parseFailed: /презентац|доклад|pptx|word|docx/i.test($('AI Agent1').first().json.input || '')
  }
}];

