// ============================================
// ОПРЕДЕЛЕНИЕ ТИПА ЗАПРОСА
// ============================================
const message = $json.message;
let promptType = 'text_assistant';

// 1. Определяем тип промпта
if (message.photo) {
  promptType = 'photo_analyst';
} else if (message.voice) {
  promptType = 'voice_assistant';
} else if (message.text) {
  const text = message.text.toLowerCase();
  if (text.includes('презентац') || text.includes('pptx') || text.includes('слайды')) {
    promptType = 'presentation_generator';
  } else if (text.includes('доклад') || text.includes('word') || text.includes('docx') || text.includes('реферат') || text.includes('отчет')) {
    promptType = 'word_generator';
  }
}

// 2. ИЗВЛЕКАЕМ ЧИСТЫЙ ТЕКСТ (решение проблемы хрупкой цепочки)
let userInput = '';
if (message.text) {
  userInput = message.text; // Текст уже нормализован нодами Code1 или Code2, либо пришел напрямую
} else {
  // Резервный вариант на всякий случай, если структура вдруг отличается
  userInput = $('Code in JavaScript2').first().json.message?.text || 
              $('Code in JavaScript1').first().json.message?.text || 
              $('Telegram Trigger').first().json.message?.text || 
              '';
}

// ============================================
// 3. ВОЗВРАТ С СИСТЕМНЫМ ПРОМПТОМ И userInput
// ============================================
return [{
  json: {
    ...$json,
    systemPrompt: PROMPTS[promptType],
    promptType: promptType,
    userInput: userInput // <--- ДОБАВЛЯЕМ ЭТО ПОЛЕ
  }
}];

const presentationData = $json.presentationData;
const chatId = $json.chatId;

// Читаем путь напрямую из переменных окружения
const outputDir = $env.PRESENTATION_OUTPUT_DIR;
const outputPath = `${outputDir}\\${chatId}.pptx`;

return [{
  json: {
    // Мы сразу формируем готовую JSON-строку для отправки
    requestBody: JSON.stringify({
      presentationData: presentationData,
      outputPath: outputPath
    })
  }
}];

const wordData = $json.wordData;
const chatId = $json.chatId;

const outputDir = $env.WORD_OUTPUT_DIR;
const outputPath = `${outputDir}\\${chatId}.docx`;

return [{
  json: {
    requestBody: {
      type: "word_document",
      wordData: wordData,
      outputPath: outputPath
    }
  }
}];
